CREATE TABLE mcp_clients(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,redirect_uri TEXT NOT NULL,created_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE TABLE mcp_consents(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES mcp_clients(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),resource TEXT NOT NULL,scopes TEXT NOT NULL,challenge TEXT NOT NULL,state TEXT NOT NULL,expires_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','denied')),code_hash TEXT UNIQUE,consumed_at INTEGER);
CREATE TABLE mcp_access_tokens(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,client_id TEXT NOT NULL REFERENCES mcp_clients(id) ON DELETE CASCADE,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),issuer TEXT NOT NULL,audience TEXT NOT NULL,scopes TEXT NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE mcp_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,actor_id TEXT REFERENCES users(id),token_id TEXT,method TEXT NOT NULL,tool TEXT,outcome TEXT NOT NULL,request_hash TEXT,created_at INTEGER NOT NULL);
CREATE INDEX mcp_audit_project_time ON mcp_audit(project_id,created_at);
CREATE INDEX mcp_token_expiry ON mcp_access_tokens(expires_at);
CREATE TRIGGER mcp_token_identity BEFORE UPDATE OF token_hash,client_id,project_id,user_id,issuer,audience,scopes,expires_at,created_at ON mcp_access_tokens BEGIN SELECT RAISE(ABORT,'mcp_token_immutable'); END;
CREATE TRIGGER mcp_client_identity BEFORE UPDATE OF project_id,owner_id,redirect_uri ON mcp_clients BEGIN SELECT RAISE(ABORT,'mcp_client_immutable'); END;
CREATE TRIGGER mcp_token_client_gate BEFORE INSERT ON mcp_access_tokens WHEN NOT EXISTS(SELECT 1 FROM mcp_clients c JOIN memberships m ON m.workspace_id=(SELECT workspace_id FROM projects WHERE id=NEW.project_id) WHERE c.id=NEW.client_id AND c.project_id=NEW.project_id AND c.owner_id=NEW.user_id AND c.revoked_at IS NULL AND m.user_id=NEW.user_id AND m.role='owner') BEGIN SELECT RAISE(ABORT,'mcp_client_revoked_or_membership_denied'); END;
CREATE TRIGGER mcp_token_no_revival BEFORE UPDATE OF revoked_at ON mcp_access_tokens WHEN OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NULL BEGIN SELECT RAISE(ABORT,'mcp_revocation_immutable'); END;
CREATE TRIGGER mcp_client_no_revival BEFORE UPDATE OF revoked_at ON mcp_clients WHEN OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NULL BEGIN SELECT RAISE(ABORT,'mcp_revocation_immutable'); END;
